using System;

public sealed class BufferedWriter : IAsyncDisposable
{
    private FileStream _stream;
    private bool _disposed;

    public BufferedWriter(string path)
    {
        _stream = new FileStream(
            path, FileMode.Create, FileAccess.Write,
            FileShare.None, 4096, useAsync: true);
    }

    public async ValueTask WriteAsync(ReadOnlyMemory<byte> data)
    {
        if (_disposed)
            throw new ObjectDisposedException(nameof(BufferedWriter));
        await _stream.WriteAsync(data);
    }

    public async ValueTask DisposeAsync()
    {
        if (_disposed) return;

        try
        {
            // Flush any buffered data to disk asynchronously
            await _stream.FlushAsync();
        }
        finally
        {
            await _stream.DisposeAsync();
            _disposed = true;
        }
    }
}

// C# 8.0 — await using for IAsyncDisposable
await using var writer = new BufferedWriter("output.json");

foreach (var record in await GetRecordsAsync())
{
    byte[] json = JsonSerializer.SerializeToUtf8Bytes(record);
    await writer.WriteAsync(json);
}
// writer.DisposeAsync() is called and awaited here.

// C# 11 — await foreach with IAsyncEnumerable
await foreach (var record in GetRecordsAsync().ConfigureAwait(false))
{
    // The enumerator is disposed automatically
    Console.WriteLine(record.Id);
}
